{
 "statements": [
  {
   "id": "3.1.1a",
   "type": "RULE",
   "force": "LEGAL",
   "force_from": "text (\"must not pass\")",
   "text": "a driver MUST NOT pass any vehicle WHEN the driver is within 30 m of a pedestrian crossover",
   "sources": [
    {
     "id": "m16",
     "quote": "You must not pass any vehicle within 30 metres of a pedestrian crossover."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  },
  {
   "id": "3.4.12a",
   "type": "RULE",
   "force": "LEGAL",
   "force_from": "text (\"must stop\")",
   "text": "a driver MUST stop WHEN the driver approaches a stopped school bus with its upper alternating red lights flashing",
   "sources": [
    {
     "id": "c1",
     "quote": "You must stop whenever you approach a stopped school bus with its upper alternating red lights flashing, regardless of whether you are behind the bus or approaching it from the front."
    }
   ],
   "flags": [],
   "links": [],
   "note": "The condition 'regardless of whether you are behind the bus or approaching it from the front' is a clarification that the rule applies to both directions, not a restriction, so it is not written as a clause."
  },
  {
   "id": "3.4.12b",
   "type": "RULE",
   "force": "LEGAL",
   "force_from": "text (\"must stop\" from c1, \"stop\" imperative in c2)",
   "text": "a driver MUST stop at least 20 m from the school bus WHEN the driver is approaching a stopped school bus with its upper alternating red lights flashing AND the driver is coming from behind the bus",
   "sources": [
    {
     "id": "c1",
     "quote": "You must stop whenever you approach a stopped school bus with its upper alternating red lights flashing, regardless of whether you are behind the bus or approaching it from the front."
    },
    {
     "id": "c2",
     "quote": "If you are coming from behind the bus, stop at least 20 metres away."
    }
   ],
   "flags": [],
   "links": [],
   "note": "The legal force comes from the lead sentence in c1 ('must stop'); c2 specifies the distance for drivers approaching from behind."
  },
  {
   "id": "3.4.12c",
   "type": "RULE",
   "force": "LEGAL",
   "force_from": "text (\"must stop\" from c1, \"Do not go\" imperative in c3)",
   "text": "a driver MUST NOT move the vehicle WHEN the driver is stopped for a school bus with its upper alternating red lights flashing UNTIL the bus moves OR the lights have stopped flashing",
   "sources": [
    {
     "id": "c1",
     "quote": "You must stop whenever you approach a stopped school bus with its upper alternating red lights flashing, regardless of whether you are behind the bus or approaching it from the front."
    },
    {
     "id": "c3",
     "quote": "Do not go until the bus moves or the lights have stopped flashing."
    }
   ],
   "flags": [],
   "links": [],
   "note": "The legal force is derived from the context of the mandatory stop in c1; c3 specifies the condition for resuming movement."
  },
  {
   "id": "3.4.12d",
   "type": "EXCEPTION",
   "force": null,
   "force_from": null,
   "text": "EXCEPTION TO 3.4.12a WHEN the driver is on a road with a median strip AND the driver is approaching the school bus from the front",
   "sources": [
    {
     "id": "c4",
     "quote": "If you are on a road with a median strip, only vehicles coming from behind the bus must stop."
    }
   ],
   "flags": [],
   "links": [
    "3.4.12a"
   ],
   "note": "This exception switches off the duty to stop for drivers approaching from the front on roads with a median strip, as they are not required to stop in this specific configuration."
  },
  {
   "id": "3.4.12e",
   "type": "FACT",
   "force": null,
   "force_from": null,
   "text": "FACT school bus drivers and other witnesses can report vehicles that have illegally passed a school bus IN Ontario",
   "sources": [
    {
     "id": "m77",
     "quote": "In Ontario, school bus drivers and other witnesses can report vehicles that have illegally passed a school bus."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  },
  {
   "id": "3.4.12f",
   "type": "RULE",
   "force": "LEGAL",
   "force_from": "context (penalty: \"can be fined heavily and get six demerit points\")",
   "text": "a driver MUST stop WHEN the driver approaches a stopped school bus with its upper alternating red lights flashing IF VIOLATED a fine AND 6 demerit points",
   "sources": [
    {
     "id": "c1",
     "quote": "You must stop whenever you approach a stopped school bus with its upper alternating red lights flashing, regardless of whether you are behind the bus or approaching it from the front."
    },
    {
     "id": "c5",
     "quote": "If you don't stop, you can be fined heavily and get six demerit points for a first offence."
    }
   ],
   "flags": [],
   "links": [],
   "note": "This statement links the duty in c1 with the penalty in c5. It is distinct from 3.4.12a to explicitly record the penalty clause as required by the method for joining duties and penalties from different passages."
  }
 ]
}
